import numpy as np
from pandas import DatetimeIndex, Timestamp

# Example 1: DatetimeIndex.year for year beyond int32 range
try:
    result = DatetimeIndex(np.array([np.iinfo(np.int64).max], dtype='M8[s]')).year
    probe("DatetimeIndex(np.array([np.iinfo(np.int64).max], dtype='M8[s]')).year", result[0])
except Exception as e:
    probe("DatetimeIndex(np.array([np.iinfo(np.int64).max], dtype='M8[s]')).year", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 2: DatetimeIndex.isocalendar() for year beyond int32 range
try:
    result = DatetimeIndex(np.array(['292277026596-12-04 15:30:07'], dtype='datetime64[s]')).isocalendar()
    probe("DatetimeIndex(np.array(['292277026596-12-04 15:30:07'], dtype='datetime64[s]')).isocalendar()", result)
